/**
 * The vendor's Ed25519 release-signing public keys (docs/superpowers/specs/2026-11-04-auto-update-design.md §7).
 *
 * Deliberately **separate** from `LICENSE_PUBLIC_KEY_PEM`, so a leak of one key is not a leak of
 * both (doc 14 §12). The private key is generated by `scripts/generate-release-keypair.mjs` into
 * `%USERPROFILE%\.buybox\` and must never appear in this repository.
 *
 * A list, not a constant: to rotate, append the next key, ship that release signed with the
 * current key, and only then switch the signer. An install that never received the new key can
 * only be moved over with the full installer.
 */
export const RELEASE_PUBLIC_KEYS_PEM: readonly string[] = [
  `-----BEGIN PUBLIC KEY-----
MCowBQYDK2VwAyEA0biAUHJgijHimB9EhAf0iTFIt3JmBa46eIlgJewq3Bk=
-----END PUBLIC KEY-----
`,
];
